import 'server-only'
import crypto from 'crypto'
import { db, globalDb, getCurrentTenantId } from '@/lib/db'

/**
 * Mode 2 (site_user_only) integration credential — a DEDICATED server-side
 * secret the CUSTOMER's backend uses to authenticate to the Sukhan identity
 * mint endpoint (POST /api/widget/identity/token).
 *
 * (feat/widget-visitor-access-modes)
 *
 * SECURITY MODEL:
 *   - cryptographically random, high entropy (48 bytes → base64url, ~64 chars)
 *   - generated by Sukhan (server-side)
 *   - the RAW value is displayed EXACTLY ONCE at generation (to the workspace
 *     admin in the dashboard); it is NEVER returned again by any GET API
 *   - only a strong SHA-256 HASH is persisted (WidgetConfig.integrationSecretHash)
 *   - tenant-bound
 *   - rotatable (generate a new secret; the old hash is replaced)
 *   - revocable (clear the hash → the customer's backend can no longer mint)
 *   - NEVER browser-visible (not in the public widget config, not in any
 *     browser bundle, not in localStorage, not in query strings, not in logs)
 *
 * DO NOT REUSE: NEXTAUTH_SECRET, the widget public API key/slug, billing
 * credentials, DB credentials, or any other unrelated secret. This is a
 * dedicated credential type.
 *
 * The integration credential is a BEARER token (the customer's server sends
 * `Authorization: Bearer <integration-secret>`). The mint endpoint hashes the
 * presented value + looks up the tenant by the hash (timing-safe compare).
 */

const RAW_LENGTH_BYTES = 48 // 384 bits of entropy — well above the 128-bit threshold

/**
 * Generate a new integration credential (raw value). The caller MUST display
 * this exactly ONCE + then discard it; only `hashIntegrationSecret(raw)` is
 * persisted.
 */
export function generateIntegrationSecret(): string {
  return crypto.randomBytes(RAW_LENGTH_BYTES).toString('base64url')
}

/** Hash an integration secret for storage (SHA-256). The raw value is discarded. */
export function hashIntegrationSecret(raw: string): string {
  return crypto.createHash('sha256').update(raw).digest('hex')
}

/** Timing-safe comparison of a presented raw secret against a stored hash. */
export function verifyIntegrationSecret(raw: string, storedHash: string | null | undefined): boolean {
  if (!storedHash) return false // no secret configured
  const presentedHash = hashIntegrationSecret(raw)
  const bufA = Buffer.from(presentedHash, 'hex')
  const bufB = Buffer.from(storedHash, 'hex')
  if (bufA.length !== bufB.length) return false
  return crypto.timingSafeEqual(bufA, bufB)
}

/**
 * Result of generating/rotating/revoking — the raw secret is present ONLY when
 * it was just (re)generated; it is `null` after revocation or on a normal GET.
 */
export interface IntegrationSecretResult {
  hasSecret: boolean
  rotatedAt: Date | null
  /** The raw secret — present EXACTLY ONCE at generation/rotation; null otherwise. */
  rawSecret: string | null
}

/**
 * Generate (or rotate) the integration secret for the CURRENT tenant. The old
 * hash (if any) is replaced — the old raw value is irrecoverable + can no
 * longer mint. The new raw value is returned EXACTLY ONCE.
 *
 * Requires an admin (manager+) session. Increments policyVersion atomically
 * (a secret rotation invalidates existing external-identity tokens minted
 * under the old secret — they reference the old policyVersion).
 */
export async function generateOrRotateIntegrationSecret(): Promise<IntegrationSecretResult> {
  const tid = getCurrentTenantId()
  if (!tid) throw new Error('no tenant context')
  const raw = generateIntegrationSecret()
  const hash = hashIntegrationSecret(raw)
  const now = new Date()
  // Atomic: replace the hash + bump policyVersion in ONE update so a rotation
  // takes effect immediately (old external-identity tokens with the old
  // policyVersion are rejected on their next protected action).
  await db.widgetConfig.update({
    where: { tenantId: tid },
    data: {
      integrationSecretHash: hash,
      integrationSecretRotatedAt: now,
      policyVersion: { increment: 1 },
    },
  })
  return { hasSecret: true, rotatedAt: now, rawSecret: raw }
}

/**
 * Revoke the integration secret (clear the hash). The customer's backend can
 * no longer mint. Increments policyVersion atomically.
 */
export async function revokeIntegrationSecret(): Promise<IntegrationSecretResult> {
  const tid = getCurrentTenantId()
  if (!tid) throw new Error('no tenant context')
  await db.widgetConfig.update({
    where: { tenantId: tid },
    data: {
      integrationSecretHash: null,
      integrationSecretRotatedAt: null,
      policyVersion: { increment: 1 },
    },
  })
  return { hasSecret: false, rotatedAt: null, rawSecret: null }
}

/**
 * The SAFE representation for normal GET APIs (dashboard). NEVER returns the
 * raw secret — only whether one exists + when it was last rotated.
 */
export async function getIntegrationSecretStatus(): Promise<IntegrationSecretResult> {
  const tid = getCurrentTenantId()
  if (!tid) throw new Error('no tenant context')
  const config = await db.widgetConfig.findUnique({
    where: { tenantId: tid },
    select: { integrationSecretHash: true, integrationSecretRotatedAt: true },
  })
  return {
    hasSecret: !!config?.integrationSecretHash,
    rotatedAt: config?.integrationSecretRotatedAt ?? null,
    rawSecret: null, // NEVER exposed on GET
  }
}

/**
 * Resolve a tenant by a presented integration secret (for the mint endpoint).
 * Hashes the presented raw value + finds the WidgetConfig whose hash matches
 * (timing-safe). Returns the tenantId + the accessMode/policyVersion, or null
 * if no tenant matches.
 *
 * Uses `globalDb` (unscoped) — the mint endpoint runs OUTSIDE any tenant
 * context (the customer's backend presents the secret, which DETERMINES the
 * tenant). This is safe because the lookup is by the secret hash, which is
 * tenant-bound + high-entropy.
 */
export async function resolveTenantByIntegrationSecret(
  presentedRaw: string,
): Promise<{ tenantId: string; accessMode: string; policyVersion: number } | null> {
  if (!presentedRaw) return null
  // Look up ALL WidgetConfig rows with a non-null integrationSecretHash + compare
  // timing-safe. (A hash index would speed this; for now the tenant count is
  // small. A future optimization: store the hash in a indexed column + do an
  // exact-match lookup by the hash, then timing-safe-verify the match.)
  const candidates = await globalDb.widgetConfig.findMany({
    where: { integrationSecretHash: { not: null } },
    select: { tenantId: true, integrationSecretHash: true, accessMode: true, policyVersion: true },
  })
  for (const c of candidates) {
    if (verifyIntegrationSecret(presentedRaw, c.integrationSecretHash)) {
      return { tenantId: c.tenantId, accessMode: c.accessMode, policyVersion: c.policyVersion }
    }
  }
  return null
}
